import {
  manifestTeu,
  manifestWeightTonnes,
  reeferCount,
  teuOf,
  verifiedGrossMassTonnes,
} from "@harbor/dispatch/cargo/manifest";

test("mass is reported in tonnes", () => {
  assert.equal(verifiedGrossMassTonnes(box("A", 20, { cargoKg: 12_000 })), 12);
  assert.throws(() => verifiedGrossMassTonnes(box("A", 20, { cargoKg: -1 })), RangeError);
});

test("verified gross mass includes tare", () => {
  assert.equal(
    verifiedGrossMassTonnes(box("A", 20, { cargoKg: 20_000, tareKg: 2_200 })),
    22.2,
  );
});

test("manifest weight sums cargo plus tare", () => {
  assert.equal(
    manifestWeightTonnes([
      box("A", 20, { cargoKg: 20_000, tareKg: 2_200 }),
      box("B", 40, { cargoKg: 10_000, tareKg: 3_800 }),
    ]),
    36,
  );
});

